    "server.test.ts": "/* eslint-disable */\nimport { describe, it, expect } from \"bun:test\";\n\n/** Mirrors `Number(process.env.SERVER_PORT || 8001)` in server.ts */\nconst DEFAULT_LISTEN_PORT = 8001;\n\nfunction listenPortFromEnv(): number {\n  return Number(process.env.SERVER_PORT || DEFAULT_LISTEN_PORT);\n}\n\n/** Mirrors greet handler: A2A passes the message's plain text; empty → \"World\". */\nfunction formatGreet(input: string): string {\n  const name = input.trim() || \"World\";\n  return `Hello, ${name}! I am {{agent_name}}.`;\n}\n\ndescribe(\"{{agent_name}}\", () => {\n  it(\"greet skill returns a formatted message from string input\", () => {\n    expect(formatGreet(\"Alice\")).toBe(\"Hello, Alice! I am {{agent_name}}.\");\n  });\n\n  it(\"greet skill treats empty/whitespace string as World\", () => {\n    expect(formatGreet(\"\")).toBe(\"Hello, World! I am {{agent_name}}.\");\n    expect(formatGreet(\"   \")).toBe(\"Hello, World! I am {{agent_name}}.\");\n  });\n\n  it(\"sandbox environment detection\", () => {\n    const originalEnv = process.env.NOVAOS_ENV;\n    process.env.NOVAOS_ENV = \"sandbox\";\n    expect(process.env.NOVAOS_ENV).toBe(\"sandbox\");\n    process.env.NOVAOS_ENV = originalEnv;\n  });\n\n  it(\"resolves default listen port to 8001 when SERVER_PORT is unset\", () => {\n    const prev = process.env.SERVER_PORT;\n    delete process.env.SERVER_PORT;\n    expect(listenPortFromEnv()).toBe(DEFAULT_LISTEN_PORT);\n    process.env.SERVER_PORT = prev;\n  });\n\n  it(\"parses SERVER_PORT as a number for listen binding\", () => {\n    const prev = process.env.SERVER_PORT;\n    const customPort = 3000;\n    process.env.SERVER_PORT = String(customPort);\n    expect(listenPortFromEnv()).toBe(customPort);\n    process.env.SERVER_PORT = prev;\n  });\n\n  it(\"treats empty SERVER_PORT as default port 8001\", () => {\n    const prev = process.env.SERVER_PORT;\n    process.env.SERVER_PORT = \"\";\n    expect(listenPortFromEnv()).toBe(DEFAULT_LISTEN_PORT);\n    process.env.SERVER_PORT = prev;\n  });\n});\n",
    "server.ts": "/**\n * {{agent_name}} — NovaOS Agent (TypeScript)\n *\n * Generated by `novaos-cli init --lang typescript --name {{agent_name}}`\n *\n * package.json pins `@novaos/agent-sdk` as a normal npm dependency —\n * `bun install`/`npm install` is how you get it, no monorepo or workspace:*\n * required. That said, the package has no registry release yet, so a fresh\n * scaffold's install will not actually succeed until it's published.\n */\n\nimport { Agent, Context, SkillResult } from \"@novaos/agent-sdk\";\nimport { z } from \"zod\";\n\nconst agent = new Agent({\n  name: \"{{agent_name}}\",\n  version: \"{{version}}\",\n});\n\n// A2A extracts the request's plain text from message.parts and passes it to\n// skill.input.parse — use z.string(), not z.object({ name: z.string() }).\nconst GreetInput = z.string();\nconst GreetOutput = z.object({ message: z.string() });\n\n/**\n * Example skill. Replace with your business logic.\n * Access platform tools via ctx.tools:\n *   Memory: use MemoryClient (novaos-client-sdk)\n *   ctx.tools.llm      — DEPRECATED; use LLMClient (novaos-client-sdk)\n *   ctx.tools.knowledge — RAG search\n *   ctx.tools.agents    — Agent-to-agent calls\n *\n * Every ctx.tools.* call made while handling a SendStreamingMessage request\n * publishes its own tool.call / tool.result event to the caller as it\n * happens — no extra code needed here to get that.\n */\nagent.skill(\"greet\", {\n  description: \"Greet a user by name\",\n  input: GreetInput,\n  output: GreetOutput,\n  handler: async (ctx: Context, input: z.infer<typeof GreetInput>): Promise<SkillResult> => {\n    const name = input.trim() || \"World\";\n    return {\n      output: { message: `Hello, ${name}! I am {{agent_name}}.` },\n      status: \"COMPLETED\",\n    };\n  },\n});\n\n// Serves A2A v1.0 JSON-RPC — both SendMessage and SendStreamingMessage — at\n// the spec's root path (A2A_JSONRPC_PATH), plus GET /health.\n// The auth-proxy sidecar strips Authorization and injects X-NovaOS-Execution-Token.\n// The SDK reads both headers automatically. For direct HTTP calls outside the SDK:\n//   const token = req.headers[\"x-novaos-execution-token\"] ?? \"\";\n//   fetch(url, { headers: { Authorization: `Bearer ${token}` } });\nagent.listen({ port: Number(process.env.SERVER_PORT || 8001) });\n",
